    def test_row_panel_floor_and_plain_captions(self):
        rows = self.card_rows(("work", {"state": "working", "workingSinceMs": NOW - 1000}),
                              ("idle", {}), ("unread", {"unread": True, "pending": True}),
                              ("drawer", {"unread": True, "pending": True, "drawer": True}),
                              ("remote", {"remote": True, "surface": "remote", "machineName": "Example", "canOpen": False,
                                          "actionRequired": True, "actionAttention": True}))
        window = self.mute_wheel_board(620, rows)
        description = asb.Gtk.AccessibleProperty.DESCRIPTION
        for identity, slot, text in (("work", "read", "The dot shows when this task ends."), ("idle", "read", ""),
                                     ("unread", "read", ""), ("unread", "drawer", "Stays unread in the drawer."),
                                     ("drawer", "drawer", "Unread on the board again.")):
            window.show_context(window.focus_widgets[identity]); self.drain(.25)
            button = window.context_menu.asb_actions[slot]
            self.assertEqual(button.asb_caption.get_label(), text)
            self.assertEqual(button.asb_caption.get_visible(), bool(text))
            if text:
                self.assert_accessible_label(button, text, description)
            window.context_menu.popdown(); self.drain(.1)
        window.show_context(window.focus_widgets["remote"]); self.drain(.3)
        panel = window.context_menu
        self.assertEqual(panel.asb_copy.asb_caption.get_label(), "Only for a session on this machine.")
        self.assert_accessible_label(panel.asb_copy, "Only for a session on this machine.", description)
        for palette in (None, {"background": "#000000", "text": "#ffffff", "muted": "#bcbcbc", "accent": "#e5a535", "divider": "#333333"},
                        {"background": "#10141c", "text": "#e8eaf0", "muted": "#9aa4b2", "accent": "#5b9dee", "divider": "#303540"}):
            window.set_palette(palette); self.settle(window)
            for button in (panel.asb_copy, panel.asb_open):
                expected = button.asb_icon.get_color()
                for part in (button.asb_label, button.asb_caption):
                    self.assertTrue(part.get_color().equal(expected), (palette, part.get_color().to_string(), expected.to_string()))

    def test_row_panel_radio_disc_and_dot_colors(self):
        window = self.mute_wheel_board()
        window.show_context(window.focus_widgets["read"]); self.drain(.3)
        panel = window.context_menu
        window.change_mute_for("1h"); window.show_mute_times(panel, True); self.drain(.3)
        for palette in (None, {"background": "#000000", "text": "#ffffff", "muted": "#bcbcbc", "accent": "#e5a535", "divider": "#333333"}):
            window.set_palette(palette); self.settle(window)
            mark = panel.asb_times["1h"].asb_icon
            pixels = self.rgba(mark)
            disc = asb.Gdk.RGBA(); dot = asb.Gdk.RGBA()
            if palette:
                disc.parse(palette["accent"]); dot.parse(palette["background"])
            else:
                _, disc = mark.get_style_context().lookup_color("accent_bg_color")
                _, dot = mark.get_style_context().lookup_color("accent_fg_color")
            rgb = lambda color: tuple(round(v * 255) for v in (color.red, color.green, color.blue))
            self.assertEqual(pixels[7][2], (*rgb(disc), 255))
            self.assertEqual(pixels[7][7], (*rgb(dot), 255))

    @unittest.skipUnless(shutil.which("xdotool") and os.environ.get("DISPLAY") in (":9", ":10"),
                         "Real page presses need xdotool and DISPLAY=:9 or :10")
    def test_row_panel_page_changes_drop_real_second_presses(self):
        # The pointer never moves between the presses: GTK keeps the old pointer target, which it picked again on the board.
        settings = asb.Gtk.Settings.get_default()
        previous = settings.get_property("gtk-enable-animations")
        self.addCleanup(settings.set_property, "gtk-enable-animations", previous)
        delay = settings.get_property("gtk-double-click-time") / 1000
        rows = self.card_rows(*((f"c{n}", {"unread": n == 0, "pending": n == 0}) for n in range(12)))
        for animations in (True, False):
            settings.set_property("gtk-enable-animations", animations)
            for change in ("tag", "back", "time"):
                for held in (False, True):
                    with self.subTest(animations=animations, change=change, held=held):
                        window = self.mute_wheel_board(720, rows)
                        window.session_action = Mock()
                        window.open_row = Mock()
                        xid = str(window.get_surface().get_xid())
                        subprocess.run(["xdotool", "windowfocus", xid], check=True)
                        window.show_context(window.focus_widgets["c0"], 20, 20); self.drain(.3)
                        panel = window.context_menu
                        choice = window.mute_for
                        if change != "tag":
                            window.show_mute_times(panel, True); self.drain(.3)
                        target = panel.asb_mute_tag if change == "tag" else panel.asb_times_back if change == "back" else panel.asb_times["always"]
                        found, point = target.compute_point(window, asb.Graphene.Point().init(target.get_width() / 2, target.get_height() / 2))
                        self.assertTrue(found)
                        left, top = window.get_surface_transform()
                        subprocess.run(["xdotool", "mousemove", "--window", xid, str(round(point.x + left)), str(round(point.y + top))], check=True)
                        self.drain(.1)
                        hold = ["sleep", ".08"] if held else []
                        # A spy behind the guards sees each press that reaches the board strip.
                        board_presses = []
                        spy = asb.Gtk.GestureClick(button=0, propagation_phase=asb.Gtk.PropagationPhase.CAPTURE)
                        spy.connect("pressed", lambda *_args: board_presses.append(True))
                        window.list_body.add_controller(spy)
                        # One xdotool call keeps both presses inside the double-click time.
                        subprocess.run(["xdotool", "mousedown", "1", *hold, "mouseup", "1", "sleep", ".03",
                                        "mousedown", "1", *hold, "mouseup", "1"], check=True)
                        self.drain(.15)
                        if change == "time":
                            # The pick mutes and closes the panel; the second press does nothing on the board.
                            self.assertFalse(panel.get_visible())
                            self.assertEqual(window.mute_for, "always")
                            window.session_action.assert_called_once_with("c0", "mute", asb.mute_body("always"))
                            window.open_row.assert_not_called()
                            self.assertEqual(board_presses, [])
                            # After the double-click time a press on the board works as usual.
                            self.drain(delay + .05)
                            subprocess.run(["xdotool", "mousedown", "1", *hold, "mouseup", "1"], check=True)
                            self.drain(.2)
                            self.assertEqual(board_presses, [True])
                            window.close(); self.drain(.1)
                            continue
                        page = "times" if change == "tag" else "main"
                        self.assertTrue(panel.get_visible())
                        self.assertEqual((panel.asb_pages.get_visible_child_name(), window.mute_for), (page, choice))
                        window.session_action.assert_not_called(); window.open_row.assert_not_called()
                        # The stale pointer target behind the panel gives no card a hover.
                        self.assertEqual([key for key, card in window.focus_widgets.items() if key != "c0" and card.has_css_class("asb-hovered")], [])
                        self.drain(delay + .05)
                        # After the double-click time the same still pointer clicks the panel row under it.
                        found, local = window.compute_point(panel, point)
                        under = panel.pick(local.x, local.y, asb.Gtk.PickFlags.DEFAULT)
                        row = under if isinstance(under, asb.Gtk.Button) else under.get_ancestor(asb.Gtk.Button)
                        self.assertIsNotNone(row)
                        clicks = []
                        row.connect("clicked", lambda *_args: clicks.append(True))
                        subprocess.run(["xdotool", "mousedown", "1", *hold, "mouseup", "1"], check=True)
                        self.drain(.2)
                        self.assertEqual(clicks, [True], row.asb_label.get_label())
                        window.close(); self.drain(.1)

    def test_row_panel_mute_tag_opens_a_list_of_times(self):
        window = self.mute_wheel_board()
        window.session_action = Mock()
        window.change_mute_for("1h")
        card = window.focus_widgets["read"]
        keys = lambda panel: SimpleNamespace(get_widget=lambda: panel)
        def header(panel):
            found, point = panel.asb_title.compute_point(window, asb.Graphene.Point().init(0, 0))
            self.assertTrue(found)
            return round(point.x), round(point.y)
        def bottom_padding(panel, row):
            content = panel.get_child().get_parent().compute_bounds(panel)[1]
            bottom = row.compute_bounds(panel)[1]
            return round(content.origin.y + content.size.height - bottom.origin.y - bottom.size.height)
        def open_list(panel):
            # The main page claims a press on the tag in the capture phase, before the Mute button.
            main = panel.asb_pages.get_child_by_name("main")
            gesture = next(controller for controller in main.observe_controllers() if isinstance(controller, asb.Gtk.GestureClick))
            self.assertEqual(gesture.get_propagation_phase(), asb.Gtk.PropagationPhase.CAPTURE)
            label = panel.asb_actions["mute"].asb_label
            for widget, claimed in ((label, False), (panel.asb_mute_tag, True)):
                found, point = widget.compute_point(main, asb.Graphene.Point().init(widget.get_width() / 2, widget.get_height() / 2))
                self.assertTrue(found)
                with patch.object(gesture, "set_state") as state:
                    window.panel_tag_pressed(gesture, 1, point.x, point.y)
                state.assert_called_once_with(asb.Gtk.EventSequenceState.CLAIMED if claimed else asb.Gtk.EventSequenceState.DENIED)
            gesture.emit("released", 1, point.x, point.y)
            self.drain(.4)
        found, top = card.compute_point(window, asb.Graphene.Point().init(0, 0))
        self.assertTrue(found)
        settings = asb.Gtk.Settings.get_default()
        for side, y in (("bottom", 20), ("top", window.get_height() - 30)):
            with self.subTest(side=side):
                window.show_context(card, card.get_width() / 2, y - top.y); self.drain(.4)
                panel = window.context_menu
                self.assertEqual(panel.get_position(), asb.Gtk.PositionType.TOP if side == "top" else asb.Gtk.PositionType.BOTTOM)
                self.assertFalse(panel.asb_pages.get_vhomogeneous())
                mute = panel.asb_actions["mute"]
                self.assertEqual(mute.get_tooltip_text(), "Click the time to choose it. Scroll or press Left and Right to change it.")
                self.assertEqual(panel.asb_mute_tag.get_tooltip_text(), "Choose how long to mute")
                before, height = header(panel), panel.get_child().get_height()
                padding = bottom_padding(panel, panel.asb_copy_full)
                open_list(panel)
                window.session_action.assert_not_called()
                self.assertEqual(panel.asb_pages.get_visible_child_name(), "times")
                self.assertEqual(header(panel), before)
                # Both placements fit the shorter time list, with no band under Always.
                self.assertLess(panel.get_child().get_height(), height)
                self.assertEqual(bottom_padding(panel, panel.asb_times["always"]), padding)
                print("panel geometry", side, "title", before[1], header(panel)[1], "padding", padding,
                      bottom_padding(panel, panel.asb_times["always"]), "height", height, panel.get_child().get_height())
                self.assertEqual(panel.asb_pages.get_height(), panel.asb_pages.get_child_by_name("times").get_height())
                # A back row, a separator, then five 30 px radio rows in MUTE_CHOICES order, with the current time checked.
                times = panel.asb_pages.get_child_by_name("times")
                children = board_children(times)
                self.assertIs(children[0], panel.asb_times_back)
                self.assertIsInstance(children[1], asb.Gtk.Separator)
                self.assertEqual(children[2:], [panel.asb_time_group])
                self.assertEqual(board_children(panel.asb_time_group), [panel.asb_times[choice] for choice in asb.MUTE_CHOICES])
                self.assertEqual(panel.asb_time_group.get_accessible_role(), asb.Gtk.AccessibleRole.RADIO_GROUP)
                self.assert_accessible_label(panel.asb_time_group, "Mute time")
                self.assert_accessible_label(panel.asb_times_back, "Back to Mute")
                self.assertEqual((icon_name(panel.asb_times_back.asb_icon), panel.asb_times_back.asb_label.get_label(),
                                  panel.asb_times_back.get_height()), ("go-previous-symbolic", "Mute", 30))
                for choice, button in panel.asb_times.items():
                    self.assertEqual((button.asb_label.get_label(), button.get_height(), button.get_accessible_role()),
                                     (asb.MUTE_WORDS[choice], 30, asb.Gtk.AccessibleRole.RADIO))
                    self.assertEqual(button.asb_icon.has_css_class("asb-radio-on"), choice == "1h")
                    # The row end says when a mute for this time would end, also as the accessible description.
                    end = asb.mute_end_text(choice, time.time() * 1000)
                    self.assertEqual(button.asb_end.get_label(), end)
                    self.assertTrue(button.asb_end.has_css_class("asb-panel-caption") and button.asb_end.has_css_class("asb-panel-key"))
                    self.assert_accessible_label(button, end, asb.Gtk.AccessibleProperty.DESCRIPTION)
                    self.assert_accessible_label(button, asb.MUTE_WORDS[choice])
                    self.assertEqual(button.asb_label.get_ellipsize(), asb.Pango.EllipsizeMode.END)
                    self.assertFalse(button.asb_label.get_layout().is_ellipsized(), choice)
                    found, bounds = button.asb_icon.compute_bounds(button)
                    self.assertEqual((found, bounds.size.width, bounds.size.height), (True, 14, 14))
                    error = self.gtk_state(self.capsule_pointer(button.__gpointer__, None), int(asb.Gtk.AccessibleState.CHECKED),
                                           ctypes.c_int(choice == "1h"))
                    self.assertFalse(error, choice)
                self.assertIs(window.get_focus(), panel.asb_times["1h"])
                # Up and Down move in the list.
                self.assertTrue(window.panel_key(keys(panel), asb.Gdk.KEY_Down, 0, asb.Gdk.ModifierType(0)))
                self.assertIs(window.get_focus(), panel.asb_times["8h"])
                self.assertTrue(window.panel_key(keys(panel), asb.Gdk.KEY_Up, 0, asb.Gdk.ModifierType(0)))
                self.assertIs(window.get_focus(), panel.asb_times["1h"])
                # The back row and Escape go back with no change and do not mute; Escape on the main page is left to the popover, which closes.
                panel.asb_times_back.emit("clicked"); self.drain(.4)
                self.assertEqual((window.mute_for, panel.asb_pages.get_visible_child_name(), window.get_focus()), ("1h", "main", mute))
                self.assertEqual(header(panel), before)
                self.assertEqual(bottom_padding(panel, panel.asb_copy_full), padding)
                print("panel return", side, "title", header(panel)[1], "padding", bottom_padding(panel, panel.asb_copy_full))
                open_list(panel)
                self.assertIs(window.get_focus(), panel.asb_times["1h"])
                self.assertTrue(window.panel_key(keys(panel), asb.Gdk.KEY_Escape, 0, asb.Gdk.ModifierType(0)))
                self.drain(.4)
                self.assertEqual((window.mute_for, panel.asb_pages.get_visible_child_name(), window.get_focus()), ("1h", "main", mute))
                self.assertFalse(window.panel_key(keys(panel), asb.Gdk.KEY_Escape, 0, asb.Gdk.ModifierType(0)))
                window.session_action.assert_not_called()
                # The slide lasts at most 200 ms, and with animations off the page changes with no motion.
                self.assertLessEqual(panel.asb_pages.get_transition_duration(), 200)
                self.assertEqual(panel.asb_pages.get_transition_type(), asb.Gtk.StackTransitionType.SLIDE_LEFT_RIGHT)
                previous = settings.get_property("gtk-enable-animations")
                settings.set_property("gtk-enable-animations", False)
                try:
                    open_list(panel)
                    self.assertEqual(panel.asb_pages.get_visible_child_name(), "times")
                    self.assertFalse(panel.asb_pages.get_transition_running())
                    panel.asb_times_back.emit("clicked")
                    self.assertFalse(panel.asb_pages.get_transition_running())
                finally:
                    settings.set_property("gtk-enable-animations", previous)
                # A pick saves the time, mutes for it, and closes the panel.
                open_list(panel)
                panel.asb_times["8h"].activate(); self.drain(.5)
                window.session_action.assert_called_once_with("read", "mute", asb.mute_body("8h"))
                self.assertEqual(window.mute_for, "8h")
                self.assertEqual(asb.read_layout(window.layout_path)["muteFor"], "8h")
                self.assertFalse(panel.get_visible())
                window.session_action.reset_mock()
                window.change_mute_for("1h")
        # A click on the rest of the Mute row still mutes for the saved time and closes the panel.
        window.show_context(card); self.drain(.3)
        panel = window.context_menu
        panel.asb_actions["mute"].emit("clicked"); self.drain(.3)
        window.session_action.assert_called_once_with("read", "mute", asb.mute_body("1h"))
        self.assertFalse(panel.get_visible())

    def test_message_courier_flight_paint_lit_icons_and_hidden_rows(self):
        def row(n, title):
            return {"id": f"m{n}", "provider": "codex", "providerLabel": "Codex", "title": title, "cwd": "/example/notes",
                    "projectName": "notes", "state": "idle", "canOpen": True, "updatedAtMs": NOW - n * 60_000}
        threads = [row(1, "Draft the release note"), row(2, "Check the parser fixtures"), row(3, "Sort the open issues")]
        at = time.time() * 1000
        def board(*messages):
            # Each pair has one fixed time, so a pair in a later dashboard is the same message.
            return {"generatedAtMs": NOW, "providers": [], "threads": threads,
                    "messages": [{"from": source, "to": target, "atMs": at + int(source[1:]) * 10 + int(target[1:])}
                                 for source, target in messages]}
        for target, name, value in ((asb.SwitchboardWindow, "refresh", lambda *_args, **_kwargs: None),
                                    (asb, "EventStream", lambda *_args, **_kwargs: SimpleNamespace(close=lambda: None, connected=False))):
            patcher = patch.object(target, name, value)
            patcher.start()
            self.addCleanup(patcher.stop)
        window = asb.SwitchboardWindow(self.application, "http://127.0.0.1:1", board(("m1", "m3")), theme_path=False, layout_path=False)
        self.addCleanup(window.close)
        window.set_default_size(700, 420)
        window.present()
        self.foreground(window)
        self.settle(window)
        strip, rows = window.list_body, window.focus_widgets
        def wait(done, limit=6):
            end = time.monotonic() + limit
            while not done() and time.monotonic() < end:
                self.drain(.02)
            self.assertTrue(done())
        # The first dashboard only marks its messages as seen.
        self.drain(.3)
        self.assertEqual(strip.flights, [])
        window.apply_dashboard(board(("m1", "m3"), ("m3", "m1")), None)
        wait(lambda: strip.flights)
        self.assertEqual(len(strip.flights), 1)
        flight = strip.flights[0]
        self.assertEqual(flight["rows"], (rows["m3"], rows["m1"]))
        for animation in flight["animations"]:
            animation.pause()
        flight["flight"] = .5
        start, end = (point[:2] for point in strip.message_ends(flight))
        head = asb.bezier_point(start, asb.message_control(start, end), end, .5)
        self.assertTrue(end[1] < head[1] < start[1] and head[0] < start[0])
        def pixel(x, y):
            strip.queue_draw()
            self.settle(window)
            snapshot = asb.Gtk.Snapshot()
            asb.Gtk.WidgetPaintable.new(strip).snapshot(snapshot, strip.get_width(), strip.get_height())
            renderer = asb.Gsk.CairoRenderer()
            renderer.realize(None)
            # The node bounds start at the first painted pixel; the viewport keeps strip coordinates.
            viewport = asb.Graphene.Rect().init(0, 0, strip.get_width(), strip.get_height())
            downloader = asb.Gdk.TextureDownloader.new(renderer.render_texture(snapshot.to_node(), viewport))
            downloader.set_format(asb.Gdk.MemoryFormat.R8G8B8A8)
            data, stride = downloader.download_bytes()
            renderer.unrealize()
            offset = int(y) * stride + int(x) * 4
            return tuple(data.get_data()[offset:offset + 4])
        accent = window.message_color()
        expected = tuple(min(255, round(channel * 255)) for channel in (accent.red, accent.green, accent.blue)) + (255,)
        painted = pixel(*head)
        self.assertTrue(all(abs(a - b) <= 3 for a, b in zip(painted, expected)), (painted, expected))
        strip.clear_flights()
        self.assertNotEqual(pixel(*head), painted)
        # A played flight ends with no frame loop at rest.
        window.apply_dashboard(board(("m1", "m3"), ("m3", "m1"), ("m2", "m1")), None)
        wait(lambda: strip.flights)
        wait(lambda: not strip.flights)

        # GNOME animations off: no flight, and both provider icons show the accent color for 2 s.
        settings = window.get_settings()
        settings.set_property("gtk-enable-animations", False)
        self.addCleanup(settings.set_property, "gtk-enable-animations", True)
        window.apply_dashboard(board(("m1", "m2")), None)
        wait(lambda: rows["m1"].has_css_class("asb-message-lit"))
        self.assertTrue(rows["m2"].has_css_class("asb-message-lit"))
        self.assertFalse(rows["m3"].has_css_class("asb-message-lit"))
        self.assertEqual(strip.flights, [])
        wait(lambda: not rows["m1"].has_css_class("asb-message-lit") and not rows["m2"].has_css_class("asb-message-lit"), 4)
        settings.set_property("gtk-enable-animations", True)

        # GTK 4.12 has no Gsk.PathBuilder (GTK 4.14): with animations on, no flight starts and both icons light.
        real_gsk = asb.Gsk
        class Gtk412:
            def __getattr__(self, name):
                if name == "PathBuilder":
                    raise AttributeError(name)
                return getattr(real_gsk, name)
        with patch.object(asb, "Gsk", Gtk412()):
            window.apply_dashboard(board(("m3", "m2")), None)
            wait(lambda: rows["m3"].has_css_class("asb-message-lit"))
            self.assertTrue(rows["m2"].has_css_class("asb-message-lit"))
            self.assertEqual(strip.flights, [])
            wait(lambda: not rows["m3"].has_css_class("asb-message-lit") and not rows["m2"].has_css_class("asb-message-lit"), 4)

        # A message to a row that search hides plays nothing.
        window.search.set_text("parser")
        wait(lambda: list(window.focus_widgets) == ["m2"])
        window.apply_dashboard(board(("m2", "m3")), None)
        self.drain(.5)
        self.assertEqual(strip.flights, [])
        self.assertFalse(rows["m2"].has_css_class("asb-message-lit"))

    def test_message_courier_waits_for_card_motion_and_uses_final_icon_centers(self):
        threads = [{"id": f"m{n}", "provider": "codex", "providerLabel": "Codex", "title": f"Sample session {n}",
                    "cwd": "/example/notes", "projectName": "notes", "state": "working" if n == 1 else "idle",
                    "canOpen": True, "updatedAtMs": NOW - n * 60_000, "workingSinceMs": NOW - 60_000}
                   for n in (1, 2, 3)]
        dashboard = {"generatedAtMs": NOW, "providers": [], "threads": threads, "messages": []}
        for target, name, value in ((asb.SwitchboardWindow, "refresh", lambda *_args, **_kwargs: None),
                                    (asb, "EventStream", lambda *_args, **_kwargs: SimpleNamespace(close=lambda: None, connected=False))):
            patcher = patch.object(target, name, value)
            patcher.start()
            self.addCleanup(patcher.stop)
        window = asb.SwitchboardWindow(self.application, "http://127.0.0.1:1", dashboard, theme_path=False, layout_path=False)
        self.addCleanup(window.close)
        window.set_default_size(700, 420)
        window.present()
        self.foreground(window)
        self.settle(window)
        strip = window.list_body
        self.assertEqual(window.row_order[:2], ["m1", "m2"])
        samples, starts = [], []
        start_messages, start_flight = window.start_messages, strip.start_flight
        def observed_messages(play):
            result = start_messages(play)
            samples.append((bool(strip.motion), len(strip.flights)))
            return result
        def observed_flight(source, target, color, ends):
            starts.append((bool(strip.motion), ends))
            start_flight(source, target, color, ends)
            for animation in strip.flights[-1]["animations"]:
                animation.pause()
        with patch.object(window, "start_messages", observed_messages), patch.object(strip, "start_flight", observed_flight):
            changed = copy.deepcopy(dashboard)
            changed["threads"][1].update(state="working", workingSinceMs=NOW + 1000)
            changed["messages"] = [{"from": "m1", "to": "m2", "atMs": time.time() * 1000}]
            window.apply_dashboard(changed, None)
            deadline = time.monotonic() + 6
            saw_motion = False
            while time.monotonic() < deadline and (not starts or strip.motion):
                self.drain(.01)
                if strip.motion:
                    saw_motion = True
                    self.assertEqual(strip.flights, [])
            self.assertTrue(saw_motion)
            self.assertIn((True, 0), samples)
            self.assertEqual(len(starts), 1)
            self.assertFalse(starts[0][0])
            self.assertEqual(len(strip.flights), 1)
            self.assertEqual(window.row_order[:2], ["m2", "m1"])
            flight = strip.flights[0]
            ends = strip.message_ends(flight)
            self.assertEqual(starts[0][1], ends)
            centers = []
            for row in flight["rows"]:
                found, bounds = row.asb_mark.compute_bounds(strip)
                self.assertTrue(found)
                centers.append((bounds.origin.x + bounds.size.width / 2, bounds.origin.y + bounds.size.height / 2))
            self.assertEqual([point[:2] for point in ends], centers)
            start, end = centers
            self.assertLess(end[1], start[1])
            ys = [start[1]]
            for progress in (.25, .5, .75):
                strip.advance_flight(flight, "flight", progress)
                self.drain(.02)
                self.assertEqual(strip.message_ends(flight), ends)
                ys.append(asb.bezier_point(start, asb.message_control(start, end), end,
                                           asb.ease_in_out_cubic(flight["flight"]))[1])
            ys.append(end[1])
            self.assertTrue(all(before > after for before, after in zip(ys, ys[1:])), ys)

    def test_ended_and_dropped_flights_free_their_animations_and_cards(self):
        threads = [{"id": f"m{n}", "provider": "codex", "providerLabel": "Codex", "title": f"Sample session {n}",
                    "cwd": "/example/notes", "projectName": "notes", "state": "idle", "canOpen": True,
                    "updatedAtMs": NOW - n * 60_000} for n in (1, 2, 3, 4)]
        at = time.time() * 1000
        def board(messages, gone=()):
            return {"generatedAtMs": NOW, "providers": [], "threads": [row for row in threads if row["id"] not in gone],
                    "messages": [{"from": source, "to": target, "atMs": at + index} for index, (source, target) in enumerate(messages)]}
        for target, name, value in ((asb.SwitchboardWindow, "refresh", lambda *_args, **_kwargs: None),
                                    (asb, "EventStream", lambda *_args, **_kwargs: SimpleNamespace(close=lambda: None, connected=False))):
            patcher = patch.object(target, name, value)
            patcher.start()
            self.addCleanup(patcher.stop)
        window = asb.SwitchboardWindow(self.application, "http://127.0.0.1:1", board([]), theme_path=False, layout_path=False)
        self.addCleanup(window.close)
        window.set_default_size(700, 420)
        window.present()
        self.settle(window)
        self.foreground(window)
        strip = window.list_body
        def wait(done, limit=6):
            end = time.monotonic() + limit
            while not done() and time.monotonic() < end:
                self.drain(.02)
            self.assertTrue(done())
        def assert_free(flight):
            self.assertEqual((flight["animations"], flight["ring_animation"], flight["edge_animation"], flight["rows"]),
                             ([], None, None, ()))
        # A flight that ends.
        window.apply_dashboard(board([("m1", "m2")]), None)
        wait(lambda: strip.flights)
        ended = strip.flights[0]
        self.assertEqual(len(ended["animations"]), 3)
        references = [weakref.ref(item) for item in ended["animations"]] + [weakref.ref(ended["rows"][1])]
        wait(lambda: not strip.flights)
        assert_free(ended)
        # A flight that the board drops while it plays.
        window.apply_dashboard(board([("m1", "m2"), ("m3", "m4")]), None)
        wait(lambda: strip.flights)
        dropped = strip.flights[0]
        self.assertEqual(dropped["rows"], (window.focus_widgets["m3"], window.focus_widgets["m4"]))
        references += [weakref.ref(item) for item in dropped["animations"]] + [weakref.ref(dropped["rows"][1])]
        strip.drop_flights([dropped])
        self.assertEqual(strip.flights, [])
        assert_free(dropped)
        # Late callbacks of a dropped flight do nothing.
        before = dict(dropped)
        strip.advance_flight(dropped, "flight", .5)
        for key in ("flight", "ring", "edge"):
            strip.flight_done(None, dropped, key)
        self.assertEqual((dropped, strip.flights), (before, []))
        # The rows of the two target cards leave the list, so the board releases the cards.
        window.apply_dashboard(board([("m1", "m2"), ("m3", "m4")], gone=("m2", "m4")), None)
        self.drain(.3)
        self.assertFalse({"m2", "m4"} & set(window.row_cache))
        gc.collect()
        self.drain(.2)
        gc.collect()
        self.assertEqual([reference() for reference in references], [None] * 8)

    def pet_board(self, layout, count=9, size=(900, 300)):
        """A foreground board with made-up cards and a layout file; board() makes a dashboard with new messages."""
        threads = [{"id": f"m{n}", "provider": "codex", "providerLabel": "Codex", "title": f"Sample session {n}",
                    "cwd": "/example/notes", "projectName": "notes", "state": "idle", "canOpen": True,
                    "updatedAtMs": NOW - n * 60_000} for n in range(1, count + 1)]
        at = time.time() * 1000
        sent = []
        def board(*messages):
            sent.extend(messages)
            return {"generatedAtMs": NOW, "providers": [], "threads": threads,
                    "messages": [{"from": source, "to": target, "atMs": at + index} for index, (source, target) in enumerate(sent)]}
        for target, name, value in ((asb.SwitchboardWindow, "refresh", lambda *_args, **_kwargs: None),
                                    (asb, "EventStream", lambda *_args, **_kwargs: SimpleNamespace(close=lambda: None, connected=False))):
            patcher = patch.object(target, name, value)
            patcher.start()
            self.addCleanup(patcher.stop)
        directory = tempfile.TemporaryDirectory(prefix="asb-pets-test-")
        self.addCleanup(directory.cleanup)
        layout_path = Path(directory.name) / "layout.json"
        layout_path.write_text(json.dumps({"version": 1, "columnWidth": 240, **layout}))
        window = asb.SwitchboardWindow(self.application, "http://127.0.0.1:1", board(), theme_path=False, layout_path=layout_path)
        self.addCleanup(window.close)
        window.set_default_size(*size)
        window.present()
        self.foreground(window)
        self.settle(window)
        self.drain(.3)
        return window, board, layout_path

    def wait_for(self, done, limit=6):
        end = time.monotonic() + limit
        while not done() and time.monotonic() < end:
            self.drain(.02)
        self.assertTrue(done())

    def strip_paint(self, window):
        """A reader of the strip paint: (x, y) to RGBA."""
        strip = window.list_body
        strip.queue_draw()
        self.settle(window)
        snapshot = asb.Gtk.Snapshot()
        asb.Gtk.WidgetPaintable.new(strip).snapshot(snapshot, strip.get_width(), strip.get_height())
        renderer = asb.Gsk.CairoRenderer()
        renderer.realize(None)
        viewport = asb.Graphene.Rect().init(0, 0, strip.get_width(), strip.get_height())
        downloader = asb.Gdk.TextureDownloader.new(renderer.render_texture(snapshot.to_node(), viewport))
        downloader.set_format(asb.Gdk.MemoryFormat.R8G8B8A8)
        data, stride = downloader.download_bytes()
        renderer.unrealize()
        data = data.get_data()
        return lambda x, y: tuple(data[int(y) * stride + int(x) * 4:int(y) * stride + int(x) * 4 + 4])

    @staticmethod
    def near(painted, color):
        return all(abs(a - int(color[index:index + 2], 16)) <= 3 for a, index in zip(painted, (1, 3, 5))) and painted[3] == 255

    def walk_pair(self, window):
        """Two cards inside the view with the same floor and far apart, so the pet walks."""
        strip = window.list_body
        for source, target in ((a, b) for a in window.row_order for b in window.row_order if a != b):
            rows = window.focus_widgets[source], window.focus_widgets[target]
            ends, flags = strip.pet_ends(rows), strip.message_ends({"rows": rows})
            if ends and ends[0][2] == ends[1][2] and ends[1][0] - ends[0][0] > 100 and not flags[0][2] and not flags[1][2]:
                return source, target
        self.fail("no two cards on one floor")

    def run_pet(self, window, board, pair):
        strip = window.list_body
        window.apply_dashboard(board(pair), None)
        self.wait_for(lambda: strip.flights)
        flight = strip.flights[0]
        for animation in flight["animations"]:
            animation.pause()
        return flight

    def crab_pixel(self, flight, ends, t):
        """A strip point in the middle of the widest crab-color run of the pose at t."""
        pet, scale = flight["pet"], flight["scale"]
        pose = asb.pet_pose(pet, scale, flight["plan"], t, *ends)
        runs, left, top, _flip = asb.pet_box(pet, scale, pose["frame"], pose["x"], pose["y"], pose["face"])
        _color, x, y, width = max((run for run in runs if run[0] == "#d97757"), key=lambda run: run[3])
        return left + (x + width // 2) * scale + scale // 2, top + y * scale + scale // 2

    def pets_preferences(self, pet="off", width=780):
        window, _board, path = self.pet_board({"pet": pet}, count=3, size=(700, 420))
        settings = window.get_settings()
        self.addCleanup(settings.set_property, "gtk-enable-animations", settings.get_property("gtk-enable-animations"))
        settings.set_property("gtk-enable-animations", True)
        window.open_preferences(); self.drain(.2)
        preferences = window.preferences_window
        preferences.set_default_size(width, 560); self.drain(.3)
        preferences.show_section("appearance"); self.drain(.05)
        return window, preferences, path

    def assert_pet_choice(self, window, index, focused=False):
        for position, tile in enumerate(window.pet_tiles):
            chosen = position == index
            self.assertEqual((tile.get_active(), tile.get_focusable()), (chosen, chosen))
            error = self.gtk_state(self.capsule_pointer(tile.__gpointer__, None), int(asb.Gtk.AccessibleState.CHECKED),
                                   ctypes.c_int(asb.Gtk.AccessibleTristate.TRUE if chosen else asb.Gtk.AccessibleTristate.FALSE))
            if error:
                message = ctypes.string_at(error).decode()
                self.g_free(error)
                self.fail(message)
        if focused:
            self.assertIs(window.preferences_window.get_focus(), window.pet_tiles[index])

    def test_pets_preference_saves_and_keeps_the_old_pet_on_error(self):
        window, preferences, layout_path = self.pets_preferences()
        tiles = window.pet_tiles
        strip = tiles[0].get_parent()
        pets_label = window.view_filter.get_parent().get_next_sibling()
        self.assertEqual((pets_label.get_label(), pets_label.get_xalign()), ("Pets", 0))
        self.assertIs(pets_label.get_next_sibling(), strip)
        self.assertEqual([tile.name for tile in tiles], list(asb.PETS))
        self.assertEqual(window.pet, "off")
        self.assertFalse(hasattr(window, "pet_setting"))
        self.assertEqual(strip.get_accessible_role(), asb.Gtk.AccessibleRole.RADIO_GROUP)
        self.assert_accessible_label(strip, "Pets")
        for tile, name in zip(tiles, ("Off", "Crab", "Pigeon", "Cat")):
            self.assertEqual(tile.get_accessible_role(), asb.Gtk.AccessibleRole.RADIO)
            self.assert_accessible_label(tile, name)
        self.assert_pet_choice(window, 0)
        caption = strip.get_next_sibling()
        self.assertEqual(caption.get_label(), "A pixel pet carries each message from card to card.")
        self.assertTrue(caption.has_css_class("caption") and caption.get_wrap() and caption.get_xalign() == 0)
        self.assertIs(caption.get_next_sibling(), window.pet_stage)
        self.assertIs(window.pet_stage.get_next_sibling(), window.width_control.get_parent())
        self.assertTrue(caption.get_mapped() and strip.get_mapped())
        tiles[3].emit("clicked"); self.drain(.1)
        self.assert_pet_choice(window, 3)
        self.assertEqual((window.pet, json.loads(layout_path.read_text())["pet"]), ("cat", "cat"))
        self.assertEqual(window.layout_error.get_label(), "")
        self.drain(.35)
        before = layout_path.read_bytes()
        with patch.object(asb, "write_layout", side_effect=OSError("Cannot save.")):
            tiles[1].emit("clicked"); self.drain(.05)
        self.assert_pet_choice(window, 3)
        self.assertEqual((window.pet, layout_path.read_bytes()), ("cat", before))
        self.assertIsNone(tiles[1].chosen_at)
        self.assertEqual(window.layout_error.get_label(), "Cannot save.")
        tiles[3].emit("clicked")
        self.assert_pet_choice(window, 3)
        tiles[0].emit("clicked"); self.drain(.1)
        self.assert_pet_choice(window, 0)
        self.assertEqual((window.pet, window.layout_error.get_label()), ("off", ""))
        self.assertNotIn("pet", json.loads(layout_path.read_text()))

    def test_pet_tiles_keyboard_wraps_and_roves_focus(self):
        window, preferences, _path = self.pets_preferences("cat")
        window.pet_tiles[3].grab_focus()
        for key, index in ((asb.Gdk.KEY_Right, 0), (asb.Gdk.KEY_Left, 3), (asb.Gdk.KEY_Home, 0),
                           (asb.Gdk.KEY_End, 3), (asb.Gdk.KEY_Down, 0), (asb.Gdk.KEY_Up, 3)):
            tile = preferences.get_focus()
            controller = next(item for item in tile.observe_controllers() if isinstance(item, asb.Gtk.EventControllerKey))
            self.assertTrue(controller.emit("key-pressed", key, 0, 0))
            self.assert_pet_choice(window, index, focused=True)
            self.assertIsNotNone(window.pet_tiles[index].chosen_at)
        self.drain(.8)
        self.assertIsNone(window.pet_tiles[0].get_parent().tick)

    def pet_widget_paint(self, widget):
        """RGBA pixels in the outer widget box, including its CSS border."""
        paintable = asb.Gtk.WidgetPaintable.new(widget)
        width, height = paintable.get_intrinsic_width(), paintable.get_intrinsic_height()
        snapshot = asb.Gtk.Snapshot()
        paintable.snapshot(snapshot, width, height)
        node = snapshot.to_node()
        self.assertIsNotNone(node)
        renderer = asb.Gsk.CairoRenderer()
        renderer.realize(None)
        try:
            downloader = asb.Gdk.TextureDownloader.new(renderer.render_texture(node, asb.Graphene.Rect().init(0, 0, width, height)))
            downloader.set_format(asb.Gdk.MemoryFormat.R8G8B8A8)
            data, stride = downloader.download_bytes()
            data = data.get_data()
        finally:
            renderer.unrealize()
        return lambda x, y: tuple(data[int(y) * stride + int(x) * 4:int(y) * stride + int(x) * 4 + 4])

    def test_pet_tiles_sizes_picture_ring_badge_and_background(self):
        window, preferences, _path = self.pets_preferences("crab")
        stage, tiles = window.pet_stage, window.pet_tiles
        self.assertEqual(stage.get_accessible_role(), asb.Gtk.AccessibleRole.IMG)
        self.assert_accessible_label(stage, "Crab carries a message between two sample cards")
        self.assertFalse(stage.get_focusable() or stage.get_can_target())
        for width, tile_width in ((420, 89), (780, 112)):
            preferences.set_default_size(width, 560); self.drain(.3)
            preferences.show_section("appearance"); self.drain(.2)
            self.assertEqual(preferences.get_width(), width)
            self.assertEqual([(tile.get_allocated_width(), tile.get_allocated_height()) for tile in tiles], [(tile_width, 92)] * 4)
            self.assertEqual(tiles[0].get_parent().get_spacing(), 8)
            self.assertEqual(stage.get_allocated_height(), 116)
            self.assertEqual(stage.get_allocated_width(), stage.get_parent().get_width())
            self.assertEqual([card.get_allocated_height() for card in stage.cards], [68, 68])
            found, outer = stage.compute_bounds(preferences)
            left, right = [card.compute_bounds(preferences)[1] for card in stage.cards]
            self.assertEqual(left.origin.x - outer.origin.x, 12)
            self.assertEqual(right.origin.x - left.origin.x - left.size.width, 12)
            self.assertEqual(outer.origin.x + outer.size.width - right.origin.x - right.size.width, 12)
            output = os.environ.get("ASB_NATIVE_TEST_SNAPSHOTS")
            if output:
                asb.save_snapshot(preferences, str(Path(output) / f"pets-gnome-{width}.png"))
        for colors in (None, CUSTOM):
            window.set_palette(colors)
            (preferences.add_css_class if colors else preferences.remove_css_class)("asb-custom")
            # The Adwaita button transition runs for 200 ms after the colors change.
            self.drain(.4)
            self.settle(preferences)
            checked, unchecked = self.pet_widget_paint(tiles[1]), self.pet_widget_paint(tiles[2])
            accent = window.message_color()
            accent = tuple(min(255, round(channel * 255)) for channel in (accent.red, accent.green, accent.blue))
            near_accent = lambda pixel: all(abs(a - b) <= 3 for a, b in zip(pixel[:3], accent)) and pixel[3] == 255
            self.assertTrue(near_accent(checked(1, 46)), checked(1, 46))
            self.assertFalse(near_accent(unchecked(1, 46)))
            self.assertTrue(tiles[1].badge.get_visible())
            self.assertFalse(tiles[2].badge.get_visible())
            self.assertEqual(tiles[1].badge.get_allocated_width(), 18)
            self.assertEqual(tiles[1].badge.get_allocated_height(), 18)
            # The icon has no ink at the center of the circle.
            self.assertTrue(near_accent(checked(tiles[1].get_allocated_width() - 15, 8)))
            self.assertFalse(near_accent(unchecked(tiles[2].get_allocated_width() - 15, 8)))
            self.assertFalse(near_accent(checked(4, 60)))
            pet = asb.load_pets()["pets"]["crab"]
            runs, left, top, _flip = asb.pet_box(pet, 2, "stand", round(tiles[1].get_allocated_width() / 2), 53, 1)
            _color, x, y, length = max((run for run in runs if run[0] == "#d97757"), key=lambda run: run[3])
            pixel = checked(left + (x + length // 2) * 2 + 1, top + y * 2 + 1)
            self.assertTrue(self.near(pixel, "#d97757"), pixel)
        output = os.environ.get("ASB_NATIVE_TEST_SNAPSHOTS")
        if output:
            asb.save_snapshot(preferences, str(Path(output) / "pets-custom-780.png"))

    def test_pet_stage_reuses_board_flights_and_stops_on_hide(self):
        window, preferences, _path = self.pets_preferences("crab")
        stage = window.pet_stage
        stage.set_active(False)
        stage.set_active(True)
        started = time.monotonic()
        self.assertIsNotNone(stage.timeout)
        self.assertFalse(stage.flights)
        self.wait_for(lambda: stage.flights, 1)
        self.assertAlmostEqual(time.monotonic() - started, .4, delta=.15)
        flight = stage.flights[0]
        self.assertEqual((flight["pet_name"], flight["scale"], flight["rows"]), ("crab", 2, tuple(stage.cards)))
        self.assertIs(asb.PetStage.start_pet, asb.SessionStrip.start_pet)
        self.assertIs(asb.PetStage.snapshot_pet, asb.SessionStrip.snapshot_pet)
        for name in ("advance_pet", "snapshot_tints", "snapshot_flights", "pet_node", "start_flight"):
            self.assertIs(getattr(asb.PetStage, name), getattr(asb.SessionStrip, name))
        # The timer is start-to-start, not an extra wait after the flight ends.
        started = time.monotonic()
        self.wait_for(lambda: not stage.flights, 5)
        self.wait_for(lambda: stage.flights, 5)
        self.assertAlmostEqual(time.monotonic() - started, 4.6, delta=.15)
        flight = stage.flights[0]
        window.pet_tiles[2].emit("clicked")
        self.assertEqual((stage.flights, flight["animations"]), ([], []))
        started = time.monotonic()
        self.wait_for(lambda: stage.flights, 1)
        self.assertAlmostEqual(time.monotonic() - started, .4, delta=.15)
        self.assertEqual(stage.flights[0]["pet_name"], "pigeon")
        self.assert_accessible_label(stage, "Pigeon carries a message between two sample cards")
        preferences.show_section("sessions"); self.drain(.05)
        self.assertEqual((stage.active, stage.timeout, stage.flights), (False, None, []))
        self.assertTrue(all(card.asb_light_timer is None for card in stage.cards))
        preferences.show_section("appearance"); self.drain(.05)
        self.assertIsNotNone(stage.timeout)
        preferences.set_default_size(420, 560); self.drain(.3)
        self.assertEqual(preferences.pages.get_visible_child_name(), "list")
        self.assertEqual((stage.active, stage.timeout, stage.flights), (False, None, []))
        preferences.show_section("appearance"); self.drain(.5)
        self.assertTrue(stage.flights)
        preferences.close(); self.drain(.05)
        self.assertEqual((stage.active, stage.timeout, stage.flights), (False, None, []))
        strip = window.pet_tiles[0].get_parent()
        self.assertEqual((strip.tick, strip.motion_signal), (None, None))
        self.assertTrue(all(card.asb_light_timer is None for card in stage.cards))

    def test_pet_stage_light_fallback_and_no_motion(self):
        window, preferences, _path = self.pets_preferences("crab")
        stage, strip = window.pet_stage, window.pet_tiles[0].get_parent()
        settings = window.get_settings()
        settings.set_property("gtk-enable-animations", False)
        for colors in (None, CUSTOM):
            window.set_palette(colors)
            (preferences.add_css_class if colors else preferences.remove_css_class)("asb-custom")
            window.pet_tiles[0 if window.pet != "off" else 3].emit("clicked")
            self.drain(.1)
            self.assertFalse(stage.flights)
            self.assertIsNone(stage.timeout)
            self.assertIsNone(strip.tick)
            self.assertTrue(all(card.has_css_class("asb-message-lit") for card in stage.cards))
            accent = window.message_color()
            for card in stage.cards:
                color = card.asb_mark.get_color()
                self.assertEqual([min(255, round(channel * 255)) for channel in (color.red, color.green, color.blue)],
                                 [min(255, round(channel * 255)) for channel in (accent.red, accent.green, accent.blue)])
            self.drain(1.7)
            self.assertTrue(all(card.has_css_class("asb-message-lit") for card in stage.cards))
            self.drain(.3)
            self.assertTrue(all(not card.has_css_class("asb-message-lit") for card in stage.cards))
        settings.set_property("gtk-enable-animations", True)
        window.pet_tiles[0].emit("clicked")
        if hasattr(asb.Gsk, "PathBuilder"):
            self.wait_for(lambda: stage.flights, 1)
            flight = stage.flights[0]
            self.assertNotIn("pet", flight)
            self.assertEqual(flight["rows"], tuple(stage.cards))
            self.assert_accessible_label(stage, "The light carries a message between two sample cards")
        # GTK 4.12 has no path builder; the two marks light instead.
        class OldGsk:
            def __getattr__(self, name):
                if name == "PathBuilder":
                    raise AttributeError(name)
                return getattr(gsk, name)
        gsk = asb.Gsk
        stage.restart()
        with patch.object(asb, "Gsk", OldGsk()):
            self.drain(.45)
            self.assertFalse(stage.flights)
            self.assertTrue(all(card.has_css_class("asb-message-lit") for card in stage.cards))
        # Without the sprites, the tiles keep their names and the stage plays the light rule.
        with patch.object(asb, "load_pets", side_effect=OSError("No sprites.")), contextlib.redirect_stderr(io.StringIO()):
            missing = asb.PetTiles(window)
            self.assertIsNone(missing.sprites)
            self.assertEqual([tile.name for tile in missing.tiles], list(asb.PETS))
            window.pet_tiles[1].emit("clicked")
            self.assertEqual(window.pet, "crab")
            self.drain(.5)
            if hasattr(asb.Gsk, "PathBuilder"):
                self.assertNotIn("pet", stage.flights[0])
            else:
                self.assertTrue(all(card.has_css_class("asb-message-lit") for card in stage.cards))

    def test_pet_tile_hover_tick_choice_and_stop(self):
        window, preferences, _path = self.pets_preferences("cat")
        strip = window.pet_tiles[0].get_parent()
        self.assertIsNone(strip.tick)
        for index in (0, 1):
            tile = window.pet_tiles[index]
            tile.hover(None, True)
            self.assertIsNotNone(strip.tick)
            self.drain(.1)
            tile.hover(None, False)
            self.assertIsNone(strip.tick)
            tile.emit("clicked")
            self.assertIsNotNone(strip.tick)
            self.drain(.75 if index == 0 else .36)
            self.assertIsNone(strip.tick)
        window.pet_tiles[2].hover(None, True)
        window.get_settings().set_property("gtk-enable-animations", False)
        self.assertIsNone(strip.tick)
        window.get_settings().set_property("gtk-enable-animations", True)
        self.assertIsNotNone(strip.tick)
        preferences.close(); self.drain(.05)
        self.assertIsNone(strip.tick)

    def test_pet_flight_paints_the_crab_the_envelope_and_empty_paws(self):
        window, board, _layout_path = self.pet_board({"view": "comfortable", "pet": "crab"})
        strip, rows = window.list_body, window.focus_widgets
        source, target = self.walk_pair(window)
        flight = self.run_pet(window, board, (source, target))
        self.assertEqual((flight["rows"], flight["pet_name"], flight["scale"]), ((rows[source], rows[target]), "crab", 2))
        self.assertTrue(rows[source].has_css_class("asb-message-lit"))
        plan, pet, scale = flight["plan"], flight["pet"], 2
        ends = strip.pet_ends(flight["rows"])
        phases = {name: (start, end) for name, start, end in plan["phases"]}
        # The tints: the accent at 15% on the empty pixels of each card, away from the pet, the icons, and the particles.
        accent = window.message_color()
        # The GNOME accent can have a channel above 1, which paints as 255.
        accent = [min(255, round(channel * 255)) for channel in (accent.red, accent.green, accent.blue)]
        flight["pet_time"] = 0
        rest = self.strip_paint(window)
        stop = asb.pet_stop(pet, scale, ends[1][0], plan["direction"])
        # The sender tint is at full alpha from 120 ms to 280 ms (520 ms - 240 ms).
        for index, t, away in ((0, 200, (ends[0][0],)), (1, plan["ta"], (ends[1][0], stop))):
            self.assertEqual(asb.pet_tints(plan, t), {index: 1})
            flight["pet_time"] = t
            tinted = self.strip_paint(window)
            _found, bounds = flight["rows"][index].compute_bounds(strip)
            left, top = math.ceil(bounds.origin.x), math.ceil(bounds.origin.y)
            right, bottom = int(bounds.origin.x + bounds.size.width), int(bounds.origin.y + bounds.size.height)
            # The 3 px corners are rounded, so their edge pixels have a lower alpha.
            corner = lambda x, y: (x < left + 3 or x >= right - 3) and (y < top + 3 or y >= bottom - 3)
            empty = [(x, y) for x in range(left, right) for y in range(top, bottom)
                     if rest(x, y)[3] == 0 and not corner(x, y) and all(abs(x - center) >= 40 for center in away)]
            self.assertGreaterEqual(len(empty), 100)
            wrong = [(x, y, tinted(x, y)) for x, y in empty
                     if abs(tinted(x, y)[3] - 38) > 2 or any(abs(a - b) > 8 for a, b in zip(tinted(x, y), accent))]
            self.assertEqual(wrong[:5], [], index)
            # The column gap next to the card has no tint; the divider is at 6 px, so this samples the clear gap.
            self.assertEqual(tinted(right + 3, (top + bottom) // 2)[3], 0, index)
        # The walk: the crab color in the middle of a crab run.
        flight["pet_time"] = sum(phases["walk"]) / 2
        paint = self.strip_paint(window)
        painted = paint(*self.crab_pixel(flight, ends, flight["pet_time"]))
        self.assertTrue(self.near(painted, "#d97757"), painted)
        # The toss: the flying envelope. Over a card of the top row, the strip cuts the top of the arc.
        flight["pet_time"] = phases["toss"][0] + 30
        x, y = asb.pet_envelope(pet, scale, plan, flight["pet_time"], ends[1])
        self.assertGreaterEqual(y, 0)
        painted = self.strip_paint(window)(x + scale / 2, y + scale / 2)
        self.assertTrue(self.near(painted, "#f3efe6"), painted)
        # The windup holds the envelope; the hop and the dive have empty paws.
        for phase, held in (("windup", True), ("hop", False), ("dive", False)):
            flight["pet_time"] = phases[phase][0] + 40
            pose = asb.pet_pose(pet, scale, plan, flight["pet_time"], *ends)
            _runs, left, top, flip = asb.pet_box(pet, scale, "toss", pose["x"], pose["y"], pose["face"])
            ex, ey = pet["frames"]["toss"]["envelope"][1 if flip else 0]
            paint = self.strip_paint(window)
            self.assertEqual(any(self.near(paint(column, row), "#f3efe6") for column in range(left + ex * scale, left + (ex + 8) * scale)
                                 for row in range(top + ey * scale, top + (ey + 6) * scale)), held, phase)
        rows[target].remove_css_class("asb-message-lit")
        strip.advance_pet(flight, plan["ta"] + 1)
        self.assertTrue(flight["arrived"] and rows[target].has_css_class("asb-message-lit"))
        # A dropped pet flight lets go of its animation and its cards.
        strip.clear_flights()
        self.assertEqual((strip.flights, flight["animations"], flight["rows"]), ([], [], ()))
        # A pet that plays to its end leaves no flight and no frame loop.
        flight = None
        window.apply_dashboard(board((target, source)), None)
        self.wait_for(lambda: strip.flights)
        self.assertIn("pet", strip.flights[0])
        self.wait_for(lambda: not strip.flights, 8)

        # GNOME animations off: both icons show the accent color, and no pet walks.
        settings = window.get_settings()
        settings.set_property("gtk-enable-animations", False)
        self.addCleanup(settings.set_property, "gtk-enable-animations", True)
        window.apply_dashboard(board((source, target)), None)
        self.wait_for(lambda: rows[source].has_css_class("asb-message-lit"))
        self.assertTrue(rows[target].has_css_class("asb-message-lit"))
        self.assertEqual(strip.flights, [])
        settings.set_property("gtk-enable-animations", True)
        self.wait_for(lambda: not rows[source].has_css_class("asb-message-lit"), 4)
        # GTK 4.12 has no Gsk.PathBuilder: the pet still walks.
        real_gsk = asb.Gsk
        class Gtk412:
            def __getattr__(self, name):
                if name == "PathBuilder":
                    raise AttributeError(name)
                return getattr(real_gsk, name)
        with patch.object(asb, "Gsk", Gtk412()):
            window.apply_dashboard(board((target, source)), None)
            self.wait_for(lambda: strip.flights)
            self.assertIn("pet", strip.flights[0])
            strip.clear_flights()

