    def test_unchecked_machine_ring_and_native_button_contrast(self):
        settings = asb.Gtk.Settings.get_default()
        self.addCleanup(settings.set_property, "gtk-enable-animations", settings.get_property("gtk-enable-animations"))
        settings.set_property("gtk-enable-animations", False)
        for colors in (None, {"background": "#000000", "text": "#ffffff", "accent": "#ffb900", "muted": "#a0a0a0", "divider": "#030303"},
                       {"background": "#10141c", "text": "#e8eaee", "accent": "#7cc4ff", "muted": "#9aa4b2", "divider": "#232a36"}):
            window = self.window()
            window.set_palette(colors)
            window.chip_buttons["laptop"].set_active(False)
            window.machine_filter.popup()
            self.drain(.1)
            rules = window.css.to_string().split("check:not(:checked) {")[1].split("}")[0]
            self.assertIn("border-left-width: 1.5px", rules)
            self.assertIn(f"border-left-color: {asb.rgba(window.palette['dim']).to_string()}", rules)
            popover = window.machine_filter.get_popover()
            bounds = popover.get_child().compute_bounds(popover)[1]
            data, stride = self.pixels(popover)
            x, y = int(bounds.get_x() + bounds.get_width() - 2), int(bounds.get_y() + 2)
            offset = y * stride + x * 4
            background = "#" + data[offset:offset + 3].hex()
            self.assertGreaterEqual(asb.contrast(window.palette["dim"], background), 3)
            window.machine_filter.popdown()
        # The nine stock GNOME dark accents: the suggested pills have readable window-colored text, and a checked toggle has
        # its label in the accent with 4.5:1 or more on its neutral fill.
        if hasattr(asb.Adw, "AccentColor"):
            window = self.window()
            native = asb.native_colors(window)
            for name in ("BLUE", "TEAL", "GREEN", "YELLOW", "ORANGE", "RED", "PINK", "PURPLE", "SLATE"):
                accent = asb.hex_color(asb.Adw.accent_color_to_standalone_rgba(getattr(asb.Adw.AccentColor, name), True))
                with patch.object(asb, "native_colors", return_value=dict(native, accent=accent)):
                    window.set_palette(None)
                self.drain(.01)
                self.assertGreaterEqual(asb.contrast(window.palette["win"], accent), 4.5)
                for button in (window.retry_button, window.empty_all_time):
                    self.assertEqual(asb.hex_color(button.get_color()), window.palette["win"])
                raised = window.palette["track"]
                for button in (window.metric_buttons["cost"], window.split_buttons["app"]):
                    self.assertEqual(asb.hex_color(button.get_color()), asb.contrast_floor(accent, window.palette["text"], raised))
                    self.assertGreaterEqual(asb.contrast(asb.hex_color(button.get_color()), raised), 4.5)
        self.assert_no_new_warnings()



    def test_round_four_cursor_circle_outline_and_share(self):
        window = self.window(period="all")
        ring = window.round
        window.set_focus_visible(True)
        ring.grab_focus()
        ring.set_hover(ring.arcs[1])
        self.drain(.25)
        self.assertEqual([layout.get_text() for layout, *_ in ring.center_layouts()][2], "27.4% of Desk")
        self.assert_accessible_label(ring, ring.hover["tip"])
        found, bounds = ring.compute_bounds(window)
        self.assertTrue(found)
        cx, cy = bounds.get_x() + ring.origin + ring.size / 2, bounds.get_y() + ring.size / 2
        # The focus circle clears the raised arc: its inner edge at outer band 146 + raise 4 + gap 1 + outline 2 + 4 px.
        radius = ring.focus_radius()
        self.assertEqual(radius - 1, ring.outer_radius() + 4 * ring.size / ring.SIZE + 3 + 4 * ring.text_scale)
        self.assertEqual(radius, 158)
        data, stride = self.pixels(window)
        def near(x, y, color):
            pixel = data[round(y) * stride + round(x) * 4:][:3]
            return all(abs(value - int(color[1 + index * 2:3 + index * 2], 16)) <= 2 for index, value in enumerate(pixel))
        for angle in (90, 180, 225, 270):
            x, y = cx + radius * math.cos(math.radians(angle)), cy + radius * math.sin(math.radians(angle))
            self.assertTrue(any(near(x + dx, y + dy, window.palette["accent"]) for dx in (-1, 0, 1) for dy in (-1, 0, 1)))
        self.assertTrue(near(cx - radius, cy - radius, window.palette["win"]))
        # Middle of the raised app arc: unchanged fill, surface gap, then accent outline.
        arc = ring.hover
        angle = math.radians((arc["a0"] + arc["a1"]) / 2)
        scale = ring.size / ring.SIZE
        def at(radius):
            return cx + (radius * scale + 4 * scale) * math.cos(angle), cy + (radius * scale + 4 * scale) * math.sin(angle)
        self.assertTrue(near(*at(arc["r1"] - 2), arc["color"]))
        # Along the raised arc, window color between its outline (to r1 + raise + 3) and the focus circle (from radius - 1).
        for step in range(1, 8):
            middle = math.radians(arc["a0"] + (arc["a1"] - arc["a0"]) * step / 8)
            for gap in (arc["r1"] * scale + 4 * scale + 4, arc["r1"] * scale + 4 * scale + 5, radius - 2.5):
                x, y = cx + gap * math.cos(middle), cy + gap * math.sin(middle)
                self.assertTrue(near(x, y, window.palette["win"]), (step, gap))
        # Exact pixel centers near a diagonal boundary are antialiased; the stroke widths are checked by snapshot calls.
        with patch.object(asb, "snapshot_stroke", wraps=asb.snapshot_stroke) as stroke:
            ring.do_snapshot(asb.Gtk.Snapshot())
        self.assertIn(6 / scale, [call.args[2] for call in stroke.call_args_list])
        self.assertIn(2 / scale, [call.args[2] for call in stroke.call_args_list])
        ring.set_hover(ring.arcs[0])
        self.assertEqual(ring.center_layouts()[2][0].get_text(), "63.0% of total")
        self.assert_no_new_warnings()

