    def test_http_304_keeps_data_skips_render_and_advances_clock(self):
        requests = []

        def request(_base, route, callback, _dispatch, method="GET", body=None, etag=None, headers=None):
            requests.append((route, etag, callback))

        window = self.Probe(self.application, "http://127.0.0.1:1", clock=lambda: 1234)
        with patch.object(asb, "request_async", request):
            window.refresh()
            route, tag, callback = requests[-1]
            self.assertEqual(tag, [None])
            tag[0] = '"first"'
            data = {"nowMs": 100, "messages": []}
            callback(data, None)
            window.refresh()
            self.assertEqual(requests[-1][1], ['"first"'])
            requests[-1][2](None, None)
        self.assertIs(window.data, data)
        self.assertEqual(window.renders, [(data, None)])
        self.assertEqual(window.data["nowMs"], 1234)

    def test_http_period_change_never_reuses_another_period_tag(self):
        requests = []

        def request(_base, route, callback, _dispatch, method="GET", body=None, etag=None, headers=None):
            requests.append((route, etag))
            if etag is not None:
                self.assertIsNone(etag[0])
                etag[0] = '"' + route + '"'
            callback({"nowMs": 100}, None)

        window = self.Probe(self.application, "http://127.0.0.1:1")
        with patch.object(asb, "request_async", request):
            window.refresh()
            window.set_period("30d")
            window.set_period("7d")
        self.assertTrue(all(tag is not None for _route, tag in requests))
        self.assertEqual([route for route, _tag in requests], ["/api/activity/messages?period=7d",
                         "/api/activity/messages?period=30d", "/api/activity/messages?period=7d"])

    def test_errors_before_and_after_data(self):
        window = self.probe([RuntimeError("Cannot load the activity. Check that ASB is running, then try again."), {"n": 1},
                             RuntimeError("Later failure.")])
        window.refresh()
        self.assertEqual(window.stack.get_visible_child_name(), "error")
        self.assertEqual(window.error_label.get_label(), "Cannot load the activity. Check that ASB is running, then try again.")
        self.assertTrue(window.error_label.get_wrap())
        self.assertEqual(window.retry_button.get_label(), "Try again")
        # The parts of the error page, 12 px apart: the icon, the title, the error text, and Try again.
        page = window.stack.get_child_by_name("error")
        self.assertEqual(page.get_spacing(), 12)
        parts, child = [], page.get_first_child()
        while child:
            parts.append(child)
            child = child.get_next_sibling()
        icon, title, clamp, command, reason_clamp, button = parts
        self.assertIs(command, window.error_command_row)
        self.assertFalse(command.get_visible())
        self.assertFalse(reason_clamp.get_visible())
        self.assertIs(reason_clamp.get_child(), window.error_reason)
        self.assertTrue(window.error_reason.get_selectable())
        self.assertEqual((icon.get_icon_name(), icon.get_pixel_size()), ("computer-fail-symbolic", 128))
        self.assertTrue(icon.has_css_class("asb-dim"))
        self.assertEqual(title.get_label(), "Cannot load test activity")
        self.assertTrue(title.has_css_class("asb-error-title"))
        self.assertEqual((clamp.get_child(), clamp.get_maximum_size()), (window.error_label, 360))
        self.assertTrue(window.error_label.has_css_class("asb-dim") and window.error_label.has_css_class("asb-error-text"))
        self.assertIs(button, window.retry_button)
        self.assertTrue(button.has_css_class("suggested-action") and button.has_css_class("pill"))
        rules = window.css.to_string()
        self.assertIn(".asb-error-title {\n  font-size: 26px;\n  font-weight: 700;", rules)
        self.assertIn(".asb-status-compact.", rules)
        self.assertIn(".asb-error-text {\n  font-size: 13px;", rules)
        window.set_palette(asb.validate_theme(CUSTOM))
        rules = window.css.to_string()
        # With custom colors: the accent background and window-colored text.
        custom = rules.split("button.suggested-action {")[1].split("}")[0].replace(" ", "")
        self.assertIn("background-color:rgb(243,198,107);", custom)
        self.assertIn("color:rgb(23,28,34);", custom)
        window.retry_button.emit("clicked")
        self.assertEqual((len(window.routes), window.stack.get_visible_child_name(), window.renders), (2, "data", [({"n": 1}, None)]))
        window.refresh()
        self.assertEqual((len(window.routes), window.stack.get_visible_child_name(), window.data), (3, "data", {"n": 1}))
        self.assertEqual(len(window.renders), 1)

    def test_no_http_response_has_recovery_and_a_separate_system_reason(self):
        for failure, reason in ((asb.URLError(ConnectionRefusedError(111, "Connection refused")), "Connection refused"),
                                (asb.URLError("timed out"), "timed out"), (OSError("Network unreachable"), "Network unreachable")):
            with self.subTest(reason=reason), patch.object(asb.LOCAL_HTTP, "open", side_effect=failure):
                with self.assertRaises(RuntimeError) as caught:
                    asb.request_json("http://127.0.0.1:1", "/api/activity/usage?period=all")
                self.assertEqual(str(caught.exception), asb.ACTIVITY_NO_ENGINE + "\n" + reason)
                window = self.probe([caught.exception])
                window.refresh()
                self.assertEqual(window.error_label.get_label(), "The ASB engine does not answer.\nStart it in a terminal:")
                # The start command stands alone on a selectable line as a chip, before the reason and Try again.
                command = window.error_command
                self.assertEqual((command.get_label(), command.get_visible(), command.get_selectable()), ("asb engine start", True, True))
                self.assertIs(command.get_parent().get_next_sibling(), window.error_reason_clamp)
                chip = window.css.to_string().split(".asb-error-command {")[1].split("}")[0]
                for rule in ('font-family: "monospace";', f"background-color: {asb.rgba(window.palette['rule']).to_string()};",
                             "border-top-left-radius: 4px", "padding-top: 2px;", "padding-left: 6px;"):
                    self.assertIn(rule.replace(" ", ""), chip.replace(" ", "").replace("\n", ""))
                self.assertEqual(window.error_reason.get_label(), reason)
                self.assertTrue(window.error_reason.get_visible() and window.error_reason_clamp.get_visible())
                self.assertTrue(window.error_reason.get_selectable())
                self.assertIn("font-size: 12px", window.css.to_string().split(".asb-error-reason {")[1].split("}")[0])
        # A server detail with a newline stays whole in the body.
        window = self.probe([RuntimeError("Server detail\nTry another period.")])
        window.refresh()
        self.assertEqual(window.error_label.get_label(), "Server detail\nTry another period.")
        self.assertFalse(window.error_reason_clamp.get_visible())
        self.assertFalse(window.error_command.get_visible())

